import React from "react";
import { motion } from "framer-motion";
import heroImg from "../../assets/hero-interview.png"; // optional, replace with your own image path

export default function Home() {
  return (
    <div className="bg-gradient-to-b from-blue-50 to-white min-h-screen flex flex-col justify-center items-center text-center px-6">
      {/* Hero Section */}
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="max-w-5xl mx-auto flex flex-col md:flex-row items-center justify-between gap-10"
      >
        {/* Text Section */}
        <div className="md:w-1/2 space-y-6">
          <motion.h1
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.7 }}
            className="text-4xl md:text-6xl font-bold text-blue-700 leading-tight"
          >
            Ace Your Interview with{" "}
            <span className="text-blue-500">AI-Powered Coaching</span>
          </motion.h1>

          <motion.p
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.4, duration: 0.7 }}
            className="text-gray-700 text-lg leading-relaxed"
          >
            Practice mock interviews, get instant AI feedback, and sharpen your
            communication skills — all in one intelligent platform built for
            your success.
          </motion.p>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.6 }}
            className="flex flex-wrap justify-center md:justify-start gap-4 mt-6"
          >
            <button className="px-8 py-3 bg-gradient-to-r from-blue-400 to-blue-600 text-white font-semibold rounded-md shadow-md hover:shadow-blue-400 hover:scale-105 transition">
              Start Interview
            </button>

            <button className="px-8 py-3 border-2 border-blue-500 text-blue-600 font-semibold rounded-md hover:bg-blue-50 hover:scale-105 transition">
              Learn More
            </button>
          </motion.div>
        </div>

        {/* Image Section */}
        <motion.div
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ delay: 0.5, duration: 0.8 }}
          className="md:w-1/2"
        >
          <img
            src={
              heroImg ||
              "https://cdn.dribbble.com/userupload/10887116/file/original-274b3f82f.png"
            }
            alt="AI Interview Coaching"
            className="w-full rounded-2xl shadow-lg hover:shadow-2xl transition"
          />
        </motion.div>
      </motion.div>

      {/* Features Section */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1, duration: 0.8 }}
        className="mt-20 max-w-6xl mx-auto grid md:grid-cols-3 gap-10"
      >
        {[
          {
            title: "Real-Time AI Feedback",
            desc: "Receive instant and precise insights on tone, clarity, and confidence.",
            icon: "💬",
          },
          {
            title: "Mock Interview Simulator",
            desc: "Practice any job role with realistic interview scenarios and timing.",
            icon: "🤖",
          },
          {
            title: "Detailed Performance Reports",
            desc: "Track your growth and identify improvement areas with ease.",
            icon: "📊",
          },
        ].map((feature, index) => (
          <motion.div
            key={index}
            whileHover={{ scale: 1.05 }}
            className="bg-white rounded-2xl shadow-lg p-8 border border-blue-100 hover:border-blue-300 transition"
          >
            <div className="text-4xl mb-4">{feature.icon}</div>
            <h3 className="text-xl font-semibold text-blue-700 mb-2">
              {feature.title}
            </h3>
            <p className="text-gray-600">{feature.desc}</p>
          </motion.div>
        ))}
      </motion.div>
    </div>
  );
}
